<?php require __DIR__.'/../db.php'; $db=connect_db($config['db']); ensure_core_tables($db); $studentId=(int)($_GET['student_id']??0); $examId=(int)($_GET['exam_id']??0); $details=[]; if($studentId>0 && $examId>0){$st=$db->prepare('SELECT sub.subject_name,m.mark FROM marks m INNER JOIN subjects sub ON sub.id=m.subject_id WHERE m.student_id=:sid AND m.exam_id=:eid ORDER BY sub.display_order');$st->execute(['sid'=>$studentId,'eid'=>$examId]);$details=$st->fetchAll()?:[];} include __DIR__.'/../layout/header.php'; include __DIR__.'/../layout/sidebar.php'; ?>
<h3>Marksheet (Printable)</h3>
<form class="row g-2 mb-3"><div class="col"><input class="form-control" name="exam_id" placeholder="Exam ID" value="<?= $examId?:'' ?>"></div><div class="col"><input class="form-control" name="student_id" placeholder="Student ID" value="<?= $studentId?:'' ?>"></div><div class="col"><button class="btn btn-primary">Load</button></div></form>
<div class="card card-body"><table class="table"><tr><th>Subject</th><th>Mark</th></tr><?php foreach($details as $d): ?><tr><td><?= h((string)$d['subject_name']) ?></td><td><?= h((string)$d['mark']) ?></td></tr><?php endforeach; ?></table><button class="btn btn-secondary" onclick="window.print()">Print / PDF</button></div>
<?php include __DIR__.'/../layout/footer.php'; ?>
